    { const char * tb_v3526 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v3526; }
    { const char * tb_v3527 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v3527; }
    { const char * tb_v3528 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v3528; }
    { const char * tb_v3529 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v3529; }
    { const char * tb_v3530 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v3530; }
    { const char * tb_v3531 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3531; }
    { const char * tb_v3532 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3532; }
    { const char * tb_v3533 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v3533; }
    { const char * tb_v3534 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3534; }
    { const char * tb_v3535 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v3535; }
    { const char * tb_v3536 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v3536; }
    { const char * tb_v3537 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v3537; }
    { const char * tb_v3538 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3538; }
    { const char * tb_v3539 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v3539; }
    { const char * tb_v3540 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v3540; }
    { const char * tb_v3541 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v3541; }
    { const char * tb_v3542 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3542; }
    { const char * tb_v3543 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v3543; }
    { const char * tb_v3544 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v3544; }
    { const char * tb_v3545 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v3545; }
    { const char * tb_v3546 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v3546; }
    { const char * tb_v3547 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v3547; }
    { const char * tb_v3548 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v3548; }
    { const char * tb_v3549 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3549; }
    { const char * tb_v3550 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v3550; }
    { const char * tb_v3551 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v3551; }
    { const char * tb_v3552 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v3552; }
    { const char * tb_v3553 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v3553; }
    { const char * tb_v3554 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v3554; }
    { const char * tb_v3555 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v3555; }
    { const char * tb_v3556 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v3556; }
    { const char * tb_v3557 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v3557; }
    { const char * tb_v3558 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v3558; }
    { const char * tb_v3559 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3559; }
    { const char * tb_v3560 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3560; }
    { const char * tb_v3561 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v3561; }
    { const char * tb_v3562 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3562; }
    { const char * tb_v3563 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v3563; }
    { const char * tb_v3564 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v3564; }
    { const char * tb_v3565 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3565; }
    { const char * tb_v3566 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v3566; }
    { const char * tb_v3567 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
    { const char * tb_v3571 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3571; }
    { const char * tb_v3572 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3572; }
    { const char * tb_v3573 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v3573; }
    { const char * tb_v3574 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3574; }
    { const char * tb_v3575 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v3575; }
    { const char * tb_v3576 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3576; }
    { const char * tb_v3577 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3577; }
    { const char * tb_v3578 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3578; }
    { const char * tb_v3579 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v3579; }
    { const char * tb_v3580 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3580; }
    { const char * tb_v3581 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3581; }
    { const char * tb_v3582 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v3582; }
    { const char * tb_v3583 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3583; }
    { const char * tb_v3584 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v3584; }
    { const char * tb_v3585 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3585; }
    { const char * tb_v3586 = "    if (!tb_gpu_back) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3586; }
    { const char * tb_v3587 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3587; }
    { const char * tb_v3588 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3588; }
    { const char * tb_v3589 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3589; }
    { const char * tb_v3590 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3590; }
    { const char * tb_v3591 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3591; }
    { const char * tb_v3592 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3592; }
    { const char * tb_v3593 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v3593; }
    { const char * tb_v3594 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3594; }
    { const char * tb_v3595 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v3595; }
    { const char * tb_v3596 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3596; }
    { const char * tb_v3597 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3597; }
    { const char * tb_v3598 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3598; }
    { const char * tb_v3599 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3599; }
    { const char * tb_v3600 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v3600; }
    { const char * tb_v3601 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3601; }
    { const char * tb_v3602 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v3602; }
    { const char * tb_v3603 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3603; }
    { const char * tb_v3604 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v3604; }
    { const char * tb_v3605 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3605; }
    { const char * tb_v3606 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3606; }
    { const char * tb_v3607 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3607; }
    { const char * tb_v3608 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v3608; }
    { const char * tb_v3609 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3609; }
    { const char * tb_v3610 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v3610; }
    { const char * tb_v3611 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3611; }
    { const char * tb_v3612 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3612; }
    { const char * tb_v3613 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3613; }
    { const char * tb_v3614 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3614; }
    { const char * tb_v3615 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3615; }
    { const char * tb_v3616 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3616; }
    { const char * tb_v3617 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3617; }
    { const char * tb_v3618 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3618; }
    { const char * tb_v3619 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3619; }
    { const char * tb_v3620 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3620; }
    { const char * tb_v3621 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3621; }
    { const char * tb_v3622 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
    { const char * tb_v3623 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3623; }
    { const char * tb_v3624 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
    { const char * tb_v3626 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3626; }
    { const char * tb_v3627 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3627; }
    { const char * tb_v3628 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3628; }
    { const char * tb_v3629 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v3629; }
    { const char * tb_v3630 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
    { const char * tb_v3632 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v3632; }
    { const char * tb_v3633 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v3633; }
    { const char * tb_v3634 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3634; }
    { const char * tb_v3635 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v3635; }
    { const char * tb_v3636 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
    { const char * tb_v3638 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v3638; }
    { const char * tb_v3639 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
    { const char * tb_v3641 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3641; }
    { const char * tb_v3642 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v3642; }
    { const char * tb_v3643 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3643; }
    { const char * tb_v3644 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v3644; }
    { const char * tb_v3645 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3645; }
    { const char * tb_v3646 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v3646; }
    { const char * tb_v3647 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3647; }
    { const char * tb_v3648 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v3648; }
    { const char * tb_v3649 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v3649; }
    { const char * tb_v3650 = "TB_API void tb_gpu_triangle(const long long *t, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3650; }
    { const char * tb_v3651 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 1u);\n"; *(const char * *)tb_grow(v_lines) = tb_v3651; }
    { const char * tb_v3652 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3652; }
    { const char * tb_v3653 = "// треугольник сетки (3D): как треугольник, плюс плоскость глубины в tb_gplane\n"; *(const char * *)tb_grow(v_lines) = tb_v3653; }
    { const char * tb_v3654 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3654; }
    { const char * tb_v3655 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3655; }
    { const char * tb_v3656 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin);\n"; *(const char * *)tb_grow(v_lines) = tb_v3656; }
    { const char * tb_v3657 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v3657; }
    { const char * tb_v3658 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
    { const char * tb_v3660 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3660; }
    { const char * tb_v3661 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3661; }
    { const char * tb_v3662 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3662; }
    { const char * tb_v3663 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3663; }
    { const char * tb_v3664 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3664; }
    { const char * tb_v3665 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v3665; }
    { const char * tb_v3666 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3666; }
    { const char * tb_v3667 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3667; }
    { const char * tb_v3668 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v3668; }
    { const char * tb_v3669 = "    long long x1 = x + 8 * size > tb_gw ? tb_gw : x + 8 * size, y1 = y + 16 * size > tb_gh ? tb_gh : y + 16 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3669; }
    { const char * tb_v3670 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3670; }
