    { const char * tb_v5289 = "    psom, mbuf, grbuf; } tb_mtl;   // psom — сетки на видеокарте (tb_vert3), mbuf — сетки, grbuf — записи draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v5289; }
    { const char * tb_v5290 = "// дождаться всех кадров, которые видеокарта ещё рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v5290; }
    { const char * tb_v5291 = "TB_API void tb_mtl_idle(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5291; }
