    { const char * tb_v5914 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5914; }
    { const char * tb_v5915 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v5915; }
    { const char * tb_v5916 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v5916; }
    { const char * tb_v5917 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v5917; }
    { const char * tb_v5918 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5918; }
    { const char * tb_v5919 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5919; }
    { const char * tb_v5920 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v5920; }
    { const char * tb_v5921 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5921; }
    { const char * tb_v5922 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5922; }
