    { const char * tb_v5924 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5924; }
    { const char * tb_v5925 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5925; }
    { const char * tb_v5926 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5926; }
    { const char * tb_v5927 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5927; }
    { const char * tb_v5928 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5928; }
    { const char * tb_v5929 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5929; }
    { const char * tb_v5930 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5930; }
    { const char * tb_v5931 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5931; }
    { const char * tb_v5932 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5932; }
    { const char * tb_v5933 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5933; }
    { const char * tb_v5934 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5934; }
    { const char * tb_v5935 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5935; }
    { const char * tb_v5936 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5936; }
    { const char * tb_v5937 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5937; }
    { const char * tb_v5938 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5938; }
    { const char * tb_v5939 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5939; }
    { const char * tb_v5940 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v5940; }
    { const char * tb_v5941 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5941; }
    { const char * tb_v5942 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v5942; }
    { const char * tb_v5943 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5943; }
    { const char * tb_v5944 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5944; }
    { const char * tb_v5945 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5945; }
    { const char * tb_v5946 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5946; }
    { const char * tb_v5947 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5947; }
    { const char * tb_v5948 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5948; }
    { const char * tb_v5949 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5949; }
    { const char * tb_v5950 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5950; }
    { const char * tb_v5951 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v5951; }
    { const char * tb_v5952 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5952; }
    { const char * tb_v5953 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v5953; }
    { const char * tb_v5954 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5954; }
    { const char * tb_v5955 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v5955; }
