    { const char * tb_v6111 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v6111; }
    { const char * tb_v6112 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v6112; }
