    { const char * tb_v6121 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6121; }
    { const char * tb_v6122 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v6122; }
    { const char * tb_v6123 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v6123; }
    { const char * tb_v6124 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v6124; }
    { const char * tb_v6125 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v6125; }
    { const char * tb_v6126 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v6126; }
    { const char * tb_v6127 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v6127; }
    { const char * tb_v6128 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v6128; }
    { const char * tb_v6129 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v6129; }
    { const char * tb_v6130 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v6130; }
    { const char * tb_v6131 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v6131; }
    { const char * tb_v6132 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v6132; }
    { const char * tb_v6133 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v6133; }
    { const char * tb_v6134 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v6134; }
    { const char * tb_v6135 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused; } tb_mesh;\n"; *(const char * *)tb_grow(v_lines) = tb_v6135; }
    { const char * tb_v6136 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6136; }
    { const char * tb_v6137 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6137; }
    { const char * tb_v6138 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v6138; }
    { const char * tb_v6139 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v6139; }
    { const char * tb_v6140 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6140; }
    { const char * tb_v6141 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6141; }
    { const char * tb_v6142 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v6142; }
    { const char * tb_v6143 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v6143; }
    { const char * tb_v6144 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6144; }
    { const char * tb_v6145 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v6145; }
    { const char * tb_v6146 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6146; }
    { const char * tb_v6147 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6147; }
    { const char * tb_v6148 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6148; }
    { const char * tb_v6149 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6149; }
    { const char * tb_v6150 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6150; }
    { const char * tb_v6151 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6151; }
    { const char * tb_v6152 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6152; }
    { const char * tb_v6153 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6153; }
    { const char * tb_v6154 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6154; }
    { const char * tb_v6155 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v6155; }
    { const char * tb_v6156 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6156; }
    { const char * tb_v6157 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v6157; }
    { const char * tb_v6158 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6158; }
    { const char * tb_v6159 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v6159; }
    { const char * tb_v6160 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v6160; }
    { const char * tb_v6161 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6161; }
