    { const char * tb_v6170 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6170; }
    { const char * tb_v6171 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v6171; }
    { const char * tb_v6172 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6172; }
    { const char * tb_v6173 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6173; }
    { const char * tb_v6174 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6174; }
    { const char * tb_v6175 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v6175; }
    { const char * tb_v6176 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v6176; }
    { const char * tb_v6177 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v6177; }
    { const char * tb_v6178 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6178; }
    { const char * tb_v6179 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6179; }
    { const char * tb_v6180 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6180; }
    { const char * tb_v6181 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6181; }
    { const char * tb_v6182 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6182; }
    { const char * tb_v6183 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v6183; }
    { const char * tb_v6184 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v6184; }
    { const char * tb_v6185 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6185; }
    { const char * tb_v6186 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6186; }
    { const char * tb_v6187 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v6187; }
    { const char * tb_v6188 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6188; }
    { const char * tb_v6189 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6189; }
    { const char * tb_v6190 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v6190; }
    { const char * tb_v6191 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6191; }
    { const char * tb_v6192 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6192; }
    { const char * tb_v6193 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6193; }
    { const char * tb_v6194 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v6194; }
    { const char * tb_v6195 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6195; }
    { const char * tb_v6196 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6196; }
    { const char * tb_v6197 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6197; }
    { const char * tb_v6198 = "    if (m->n == m->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6198; }
    { const char * tb_v6199 = "        m->cap = m->cap ? m->cap * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v6199; }
    { const char * tb_v6200 = "        m->t = (uint32_t *)realloc(m->t, sizeof(uint32_t) * 3 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v6200; }
    { const char * tb_v6201 = "        m->c = (uint32_t *)realloc(m->c, sizeof(uint32_t) * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v6201; }
    { const char * tb_v6202 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6202; }
    { const char * tb_v6203 = "    uint32_t *t = m->t + 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6203; }
    { const char * tb_v6204 = "    t[0] = tb_mesh_vertex(m, x1, y1, z1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6204; }
    { const char * tb_v6205 = "    t[1] = tb_mesh_vertex(m, x2, y2, z2);\n"; *(const char * *)tb_grow(v_lines) = tb_v6205; }
    { const char * tb_v6206 = "    t[2] = tb_mesh_vertex(m, x3, y3, z3);\n"; *(const char * *)tb_grow(v_lines) = tb_v6206; }
    { const char * tb_v6207 = "    m->c[m->n++] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6207; }
    { const char * tb_v6208 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6208; }
    { const char * tb_v6209 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6209; }
    { const char * tb_v6210 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6210; }
    { const char * tb_v6211 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v6211; }
    { const char * tb_v6212 = "    for (int i = 0; i < 3; i++) f[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v6212; }
    { const char * tb_v6213 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v6213; }
    { const char * tb_v6214 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v6214; }
    { const char * tb_v6215 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v6215; }
    { const char * tb_v6216 = "    l = sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6216; }
    { const char * tb_v6217 = "    for (int i = 0; i < 3; i++) r[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v6217; }
    { const char * tb_v6218 = "    double u[3] = { f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v6218; }
    { const char * tb_v6219 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v6219; }
    { const char * tb_v6220 = "    for (int i = 0; i < 3; i++) { tb_cam[3 + i] = r[i]; tb_cam[6 + i] = u[i]; tb_camf[i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6220; }
    { const char * tb_v6221 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6221; }
    { const char * tb_v6222 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v6222; }
    { const char * tb_v6223 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6223; }
    { const char * tb_v6224 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v6224; }
    { const char * tb_v6225 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v6225; }
    { const char * tb_v6226 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v6226; }
