    { const char * tb_v6245 = "    if (m->nv > tb_3vcap) { tb_3vcap = m->nv * 2; tb_3vs = (tb_3v *)realloc(tb_3vs, sizeof(tb_3v) * tb_3vcap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6245; }
