    { const char * tb_v6248 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;   // та же рамка, что в tb_poly_draw\n"; *(const char * *)tb_grow(v_lines) = tb_v6248; }
