    { const char * tb_v6337 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6337; }
    { const char * tb_v6338 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): изнутри её не видно,\n"; *(const char * *)tb_grow(v_lines) = tb_v6338; }
    { const char * tb_v6339 = "// поэтому грани, повёрнутые от камеры, можно не рисовать. Знак объёма говорит, куда смотрят грани.\n"; *(const char * *)tb_grow(v_lines) = tb_v6339; }
    { const char * tb_v6340 = "// 0 — рисовать все, -1 — пропускать треугольники с площадью < 0 на экране, 1 — с площадью > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v6340; }
    { const char * tb_v6341 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6341; }
    { const char * tb_v6342 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6342; }
